mapper.body:
{
  "model": "anthropic/claude-sonnet-4-6",
  "max_tokens": 300,
  "temperature": 0.7,
  "messages": [
    {
      "role": "system",
      "content": "You write short friendly emails."
    },
    {
      "role": "user",
      "content": "Write a 3-sentence email asking {{1.payload.invitee.name}} to leave a Google review for {{env.CLIENT_NAME}}. Warm, never pushy. Return only the email body."
    }
  ]
}

{
  "from": "{{env.RESEND_FROM_NAME}} <{{env.RESEND_FROM_ADDRESS}}>",
  "to": ["{{1.payload.invitee.email}}"],
  "subject": "How did we do? Quick review request",
  "text": "{{3.body.choices[0].message.content}}

{{env.GOOGLE_REVIEW_LINK}}",
  "html": "<div style="font-family:Arial,Helvetica,sans-serif;max-width:560px;margin:0 auto;color:#222;line-height:1.7;">{{replace(replace(3.body.choices[0].message.content, '

', '</p><p>'), '
', '<br>')}}
<p style="margin-top:24px;"><a href="{{env.GOOGLE_REVIEW_LINK}}" style="background:#4285F4;color:#ffffff;text-decoration:none;padding:12px 24px;border-radius:6px;font-weight:bold;display:inline-block;">Leave a Google Review</a></p>
<p style="font-size:13px;color:#888;">Or copy and paste this link:<br><a href="{{env.GOOGLE_REVIEW_LINK}}">{{env.GOOGLE_REVIEW_LINK}}</a></p></div>"
}

{
  "properties": {
    "hs_note_body": "Review request sent \u2014 {{formatDate(now, 'YYYY-MM-DD HH:mm', 'America/New_York')}} ET. Invitee: {{1.payload.invitee.name}} ({{1.payload.invitee.email}}). Email sent from {{env.RESEND_FROM_ADDRESS}}. Google Review link: {{env.GOOGLE_REVIEW_LINK}}. Sent via Make.com Scenario J.",
    "hs_timestamp": "{{formatDate(now, 'x')}}"
  },
  "associations": [
    {
      "to": {
        "id": "{{5.body.results[0].id}}"
      },
      "types": [
        {
          "associationCategory": "HUBSPOT_DEFINED",
          "associationTypeId": 202
        }
      ]
    }
  ]
}

{
  "from": "{{env.CWI_ALERT_FROM_ADDRESS}}",
  "to": ["{{env.ADMIN_EMAIL}}"],
  "subject": "[ERROR] Make.com \u2014 Scenario J Review Request Failed",
  "html": "<h2 style=\"color:#b00020;\">\u26a0\ufe0f Scenario J \u2014 Review Request Failed</h2><p>A step in the automated Google Review Request flow failed. The review email may NOT have been delivered to the invitee \u2014 please verify and follow up manually.</p><hr><h3>Invitee</h3><ul><li><strong>Name:</strong> {{1.payload.invitee.name}}</li><li><strong>Email:</strong> {{1.payload.invitee.email}}</li><li><strong>Event Name:</strong> {{ifempty(1.payload.event_type.name, 'N/A')}}</li><li><strong>Scheduled At:</strong> {{ifempty(1.payload.event.start_time, 'N/A')}}</li></ul><hr><h3>Error Details</h3><ul><li><strong>Error Message:</strong> {{error.message}}</li><li><strong>Failed Module:</strong> {{error.module}}</li><li><strong>Scenario Run ID:</strong> {{scenario.runId}}</li><li><strong>Timestamp:</strong> {{formatDate(now, 'YYYY-MM-DD HH:mm:ss', 'America/New_York')}} ET</li></ul><hr><p style=\"color:#888;font-size:12px;\"><em>Automated alert from Make.com CWI Automation \u2014 Scenario J: Automated Google Review Request. Owner: brian@cwiai.net / (734) 812-9971.</em></p>"
}
